{
  "name": "opencode-plugin-utf8",
  "version": "1.0.0",
  "description": "OpenCode plugin that ensures UTF-8 encoding for shell environments, fixing Chinese character garbled text on Windows",
  "type": "module",
  "main": "src/index.js",
  "files": [
    "src/",
    "README.md",
    "LICENSE",
    "CHANGELOG.md"
  ],
  "scripts": {
    "test": "vitest run",
    "test:watch": "vitest"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "utf-8",
    "encoding",
    "windows",
    "chinese",
    "python",
    "powershell"
  ],
  "author": "elvisw",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/elvisw/opencode-plugin-utf8.git"
  },
  "bugs": {
    "url": "https://github.com/elvisw/opencode-plugin-utf8/issues"
  },
  "homepage": "https://github.com/elvisw/opencode-plugin-utf8#readme",
  "devDependencies": {
    "vitest": "^3.1.1"
  }
}
